import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] exams = new int[n][2];
        for (int i = 0; i < n; i++) {
            exams[i][0] = sc.nextInt();
            exams[i][1] = sc.nextInt();
        }
        Arrays.sort(exams, (a, b) -> {
            if (a[0] != b[0]) {
                return Integer.compare(a[0], b[0]);
            }
            return Integer.compare(a[1], b[1]);
        });

        PriorityQueue<Integer> ends = new PriorityQueue<>();
        for (int[] exam : exams) {
            String label = exam[0] + "-" + exam[1];
            if (!ends.isEmpty() && ends.peek() <= exam[0]) {
                ends.poll();
                System.out.println(label + ": reuses a room");
            } else {
                System.out.println(label + ": new room");
            }
            ends.offer(exam[1]);
        }
        System.out.println("Rooms: " + ends.size());
    }
}

